android.extraProguardRules:
-keepattributes *Annotation*,Signature,InnerClasses,EnclosingMethod,SourceFile,LineNumberTable
-keep,includedescriptorclasses class com.facebook.react.bridge.** { *; }
-keep,includedescriptorclasses class com.facebook.react.turbomodule.core.** { *; }
-keep class com.facebook.jni.** { *; }
-keep class com.facebook.hermes.** { *; }
-keep class com.facebook.react.devsupport.** { *; }
-dontwarn com.facebook.react.**
-keepclassmembers class * { @com.facebook.react.uimanager.annotations.ReactProp <methods>; @com.facebook.react.uimanager.annotations.ReactPropGroup <methods>; @com.facebook.react.bridge.ReactMethod <methods>; }
-keepclasseswithmembers class * { @com.facebook.react.bridge.ReactMethod <methods>; }
-keep class expo.modules.** { *; }
-keep class expo.modules.kotlin.** { *; }
-keepclassmembers class ** { @expo.modules.core.interfaces.ExpoMethod <methods>; }
-dontwarn expo.modules.**
-keep class kotlin.Metadata { *; }
-keepclassmembers class kotlinx.coroutines.** { volatile <fields>; }
-dontwarn kotlinx.coroutines.**
-dontwarn kotlin.**
-dontwarn okhttp3.**
-dontwarn okio.**
-dontwarn org.conscrypt.**
-keep public class com.horcrux.svg.** { *; }
-keep class com.reactnativecommunity.webview.** { *; }
-keep class com.reactnativecommunity.asyncstorage.** { *; }
-keep class com.reactnativecommunity.netinfo.** { *; }
-keep class com.reactnativevolumemanager.** { *; }
-keep class com.google.firebase.** { *; }
-keep class expo.modules.notifications.** { *; }
-dontwarn com.google.firebase.**
-repackageclasses ''
-allowaccessmodification
